function useIsMobile() {
  const [m, setM] = useState(window.innerWidth < 768);
  useEffect(() => {
    const fn = () => setM(window.innerWidth < 768);
    window.addEventListener("resize", fn);
    return () => window.removeEventListener("resize", fn);
  }, []);
  return m;
}

function useEmailJS() {
  useEffect(() => {
    emailjs.init(EMAILJS_PUBLIC_KEY);
  }, []);
  return true;
}

function Logo({ size = 40, light = false }) {
  return (
    <img src="data:image/png;base64," alt="MaVilleSaine"
      style={{ height:160, width:"auto", objectFit:"contain" }}
    />
  );
}

// ── NAVBAR ────────────────────────────────────────────────────
function Navbar() {
  const [scrolled, setScrolled] = useState(false);
  const mobile = useIsMobile();
  useEffect(() => {
    const fn = () => setScrolled(window.scrollY > 20);
    window.addEventListener("scroll", fn);
    return () => window.removeEventListener("scroll", fn);
  }, []);
  const go = id => document.getElementById(id)?.scrollIntoView({ behavior:"smooth" });
  return (
    <nav style={{ position:"fixed", top:0, left:0, right:0, zIndex:100,
      background: scrolled ? "rgba(255,255,255,0.97)" : "#fff",
      boxShadow: scrolled ? "0 2px 20px rgba(0,0,0,0.08)" : "0 1px 0 #e2e8f0",
      backdropFilter:"blur(8px)", transition:"all 0.3s" }}>
      <div style={{ maxWidth:1100, margin:"0 auto", padding:"0 32px", height:68,
        display:"flex", alignItems:"center", justifyContent:"space-between" }}>
        <Logo size={42} />
        <div style={{ display: mobile ? "none" : "flex", gap:26, alignItems:"center" }}>
          {[["gratuit","100% Gratuit"],["fonctionnalites","Fonctionnalités"],["telecharger","L'app citoyenne"],["tarifs","Tarifs"],["faq","FAQ"],["contact","Contact"]].map(([id,l])=>(
            <span key={id} onClick={()=>go(id)} style={{ fontSize:14, color:G.g500, cursor:"pointer", fontWeight:500 }}
              onMouseEnter={e=>e.target.style.color=G.vert} onMouseLeave={e=>e.target.style.color=G.g500}>{l}</span>
          ))}
          <button onClick={()=>go("contact")} style={{ background:G.vert, color:"#fff", padding:"9px 22px",
            borderRadius:10, fontSize:14, fontWeight:700, border:"none", cursor:"pointer",
            boxShadow:`0 4px 12px ${G.vert}44` }}>
            Démo gratuite
          </button>
        </div>
      </div>
    </nav>
  );
}

